"""Semantic version sorting per SemVer 2.0.0 precedence."""


def _parse(version):
    core = version
    plus = core.find('+')
    if plus != -1:
        core = core[:plus]
    prerelease = None
    dash = core.find('-')
    if dash != -1:
        core, prerelease = core[:dash], core[dash + 1:]
    major, minor, patch = core.split('.')
    return int(major), int(minor), int(patch), prerelease


def _pre_key(prerelease):
    # A version with a pre-release has lower precedence than the same
    # version without one, so mark the absence with a higher value.
    if prerelease is None:
        return (1,)
    ids = []
    for ident in prerelease.split('.'):
        if ident.isdigit():
            ids.append((0, int(ident), ''))
        else:
            ids.append((1, 0, ident))
    return (0, tuple(ids))


def _key(version):
    major, minor, patch, prerelease = _parse(version)
    return (major, minor, patch, _pre_key(prerelease))


def sort_versions(vs):
    """Return the versions sorted by SemVer precedence (lowest first).

    Build metadata is ignored for ordering and equal versions retain
    their input order (stable sort).
    """
    return sorted(vs, key=_key)
